function OverseaManagePersonnelRoleFeedCell:RefreshShow(goodsId)
	self.goodsId = goodsId
	self:RefreshNodeShow()
end

function OverseaManagePersonnelRoleFeedCell:RefreshNodeShow()
	local goodsVo = GoodsConfMgr:GetInstance():GetGoodsVoById(self.goodsId)
	if isNotNull(goodsVo) then
		---@type GoodNodeMB
		local goodNodeMbEnv = CfUtils.GetLuaScr(self.GoodNode,Constants.UILuaTablePath.GoodNodeMB)
		local num = GoodsUtils.GetThingNo(self.goodsId)
		goodNodeMbEnv:Reload({
			goodsId = self.goodsId,
			text = string.format("x%d", num),
			showNum = false
		})
		CfUtils.FillText(self.TextNumber, "+"..goodsVo.effectNum)
		goodNodeMbEnv:SetClickButtonAction(function()
			if num > 0 then
				if self.callBack then
					self.callBack(self.goodsId)
				end
			else
				GameUtils.Toast(localize("道具不足"))
			end
		end)
		goodNodeMbEnv:SetEnoughState(num <= 0)
	end
end

function OverseaManagePersonnelRoleFeedCell:OnDestroy()
	self.controller = nil--luabehaviour 中CSharp对象
	self:Delete()
end

return OverseaManagePersonnelRoleFeedCell